<script setup lang="ts">
import {localize} from './localization';

import ZoomViewport from './ZoomViewport.vue';
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
import {printPageSvg} from '../../../packages/manufacturing/print-pages';
import type {PrintPreview} from '../../../packages/schema/index';
const props=defineProps<{preview:PrintPreview;language:'zh'|'en';busy:boolean}>(),emit=defineEmits<{close:[];output:[format:'pdf'|'print',pages:number[]]}>();
const zh=computed(()=>props.language==='zh'),plan=computed(()=>props.preview.plan),current=ref(1),chosen=ref(props.preview.plan.pages.map(p=>p.number)),closeButton=ref<HTMLButtonElement>();
const dialog=ref<HTMLElement>(),tile=computed(()=>plan.value.pages.find(p=>p.number===current.value)!),uri=(svg:string)=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg),sheet=computed(()=>uri(printPageSvg(props.preview.svg,plan.value,tile.value))),overview=computed(()=>uri(props.preview.svg));
const all=computed(()=>chosen.value.length===plan.value.pages.length);function toggleAll(){chosen.value=all.value?[]:plan.value.pages.map(p=>p.number);}
function close(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();emit('close');}else if(event.key==='Tab'){const focusable=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled])')??[]).filter(el=>el.getClientRects().length),first=focusable[0],last=focusable.at(-1);if(first&&(!dialog.value?.contains(document.activeElement)||event.shiftKey&&document.activeElement===first||!event.shiftKey&&document.activeElement===last)){event.preventDefault();(event.shiftKey?last:first)?.focus();}}}
let previous:HTMLElement|null=null;onMounted(()=>{previous=document.activeElement as HTMLElement;closeButton.value?.focus();window.addEventListener('keydown',close);});onBeforeUnmount(()=>{window.removeEventListener('keydown',close);previous?.focus();});
</script>
<template><div class="print-preview-backdrop" @click.self="emit('close')"><section ref="dialog" class="print-preview" role="dialog" aria-modal="true" :aria-label="zh?'分页与拼接预览':localize('Page and assembly preview')"><header><div><strong>{{zh?'分页与拼接预览':localize('Page and assembly preview')}}</strong><small>{{plan.paper.widthMm}} × {{plan.paper.heightMm}} mm · {{plan.columns}} × {{plan.rows}} · {{plan.pages.length}} {{zh?'页':localize('pages')}} · 1:1 / 100%</small></div><button ref="closeButton" :aria-label="zh?'关闭拼接预览':localize('Close print preview')" @click="emit('close')">×</button></header><p>{{zh?'按实际尺寸打印，关闭“适合页面”。裁掉空白边距，重叠相同轮廓并对齐十字标记后拼接。屏幕预览缩放不会改变打印比例。':localize('Print at actual size (100%); turn off Fit to page. Trim blank margins, overlap matching outlines and align registration crosses. Screen zoom does not affect printing.')}}</p><div class="print-preview-content"><section class="assembly-preview"><strong>{{zh?'整幅拼接位置':localize('Assembly map')}}</strong><ZoomViewport :view-box="`0 0 ${plan.widthMm} ${plan.heightMm}`" label="Assembly preview" :language="language" v-slot="{viewBox}"><svg class="assembly-board" :viewBox="viewBox" aria-label="完整纸样"><image :href="overview" :width="plan.widthMm" :height="plan.heightMm"/><g v-for="p in plan.pages" :key="p.number" @click="current=p.number"><rect :x="p.xMm" :y="p.yMm" :width="plan.contentWidthMm" :height="plan.contentHeightMm" :fill="p.number===current?'color-mix(in srgb,var(--studio-sky) 20%,transparent)':'transparent'" stroke="var(--studio-teal)" :stroke-width="Math.max(plan.widthMm,plan.heightMm)/500"/><text :x="p.xMm+4" :y="p.yMm+12" :font-size="Math.max(plan.widthMm,plan.heightMm)/35" fill="var(--studio-deep)">{{p.number}} · {{p.row}},{{p.column}}</text></g></svg></ZoomViewport><small>{{zh?'边距':localize('Margin')}} {{plan.paper.marginMm}} mm · {{zh?'重叠':localize('Overlap')}} {{plan.paper.overlapMm}} mm · {{zh?'拼接步距':localize('Assembly step')}} {{plan.stepXmm}} × {{plan.stepYmm}} mm</small></section><section class="page-preview"><strong>{{zh?'当前打印页':localize('Print page')}} {{current}} / {{plan.pages.length}}</strong><ZoomViewport :view-box="`0 0 ${plan.paper.widthMm} ${plan.paper.heightMm}`" label="Print page preview" :language="language" v-slot="{viewBox}"><svg class="print-sheet-view" :viewBox="viewBox" :aria-label="(zh?'打印页 ':localize('Print page '))+current"><image :href="sheet" :width="plan.paper.widthMm" :height="plan.paper.heightMm"/></svg></ZoomViewport></section></div><div class="print-page-selection"><label><input type="checkbox" :checked="all" @change="toggleAll">{{zh?'全选打印页':localize('Select all pages')}}</label><div v-for="p in plan.pages" :key="p.number"><input type="checkbox" v-model="chosen" :value="p.number" :aria-label="(zh?'选择打印页 ':localize('Select print page '))+p.number"><button :class="{active:current===p.number}" @click="current=p.number">{{p.number}} · {{p.row}},{{p.column}}</button></div></div><footer><span>{{chosen.length}} / {{plan.pages.length}} {{zh?'页已选择':localize('pages selected')}}</span><button :disabled="busy||!chosen.length" @click="emit('output','pdf',[...chosen])">{{zh?'导出勾选页 PDF':localize('Export selected pages PDF')}}</button><button class="primary" :disabled="busy||!chosen.length" @click="emit('output','print',[...chosen])">{{zh?'打印勾选页':localize('Print selected pages')}}</button></footer></section></div></template>
<style scoped>.print-preview-backdrop{position:fixed;inset:0;background:color-mix(in srgb,var(--studio-deep) 62%,transparent);z-index:35;display:grid;place-items:center;padding:18px}.print-preview{width:min(1050px,100%);max-height:95vh;display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--border);border-radius:18px;overflow:hidden}.print-preview header,.print-preview footer{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 18px;flex-shrink:0}.print-preview header small{display:block;margin-top:5px}small,p{font-size:11px;color:var(--text-muted);line-height:1.7}.print-preview>p{margin:0;padding:0 18px 12px}.print-preview-content{display:grid;grid-template-columns:1fr 1fr;gap:18px;overflow:auto;min-height:0;padding:10px 18px;background:var(--panel-soft)}.print-preview-content>section{min-width:0}.print-preview-content strong{font-size:12px;display:block;margin-bottom:8px}.print-sheet-view{height:52vh;background:white}.assembly-board{height:52vh;margin-inline:auto;position:relative;width:100%;background:white;overflow:hidden}.assembly-board img,.assembly-board svg{position:absolute;inset:0;width:100%;height:100%}.assembly-board svg g{cursor:pointer}.page-preview img{width:100%;max-height:52vh;object-fit:contain;object-position:top;background:white}.print-page-selection{display:flex;flex-wrap:wrap;gap:8px;padding:12px 18px;max-height:105px;overflow:auto;flex-shrink:0}.print-page-selection>div,.print-page-selection>label{display:flex;align-items:center;gap:4px;font-size:11px}.print-page-selection button{padding:5px 8px}.print-page-selection input{width:auto}.print-preview footer{height:auto;min-height:60px;font-size:12px;border-top:1px solid var(--border)}.print-preview footer span{flex:1}@media(max-width:700px){.print-preview-content{grid-template-columns:1fr}.page-preview img{max-height:40vh}.print-preview footer{flex-wrap:wrap}}</style>
